INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, verification_status, verification_note, endpoint_verified_at, policy_basis, adapter_profile, registry_version) VALUES ('src:seoul:press', 'org:서울특별시', 'HTML', 'HTMLBoardAdapter', 'https://www.seoul.go.kr', 'https://www.seoul.go.kr/news/news_report.do', '["www.seoul.go.kr"]', 'ENDPOINT_VERIFIED', '보도자료 목록(news_report.do, bbsNo=158). robots.txt가 /news 를 Allow. 원문 주소(nttNo) 열람 확인. 공식 RSS 서버(rss.seoul.go.kr)는 응답하지 않음.', 1791037800, '개별 이용조건(공공누리 유형 등)과 공개 표시 권한은 운영자 확인 전이라 승인 대기 상태다.', '{"link":"fnTbbsView\\(''(?<id>\\d+)''\\)","url":"https://www.seoul.go.kr/news/news_report.do?bbsNo=158&nttNo={id}","title":"text"}', 'seed-metro-2026-10-04') ON CONFLICT(source_id) DO UPDATE SET method = excluded.method, adapter = excluded.adapter, homepage_url = excluded.homepage_url, endpoint_url = excluded.endpoint_url, allowed_hosts = excluded.allowed_hosts, verification_status = excluded.verification_status, verification_note = excluded.verification_note, endpoint_verified_at = excluded.endpoint_verified_at, adapter_profile = excluded.adapter_profile, registry_version = excluded.registry_version, approval_status = CASE WHEN excluded.verification_status = 'ENDPOINT_VERIFIED' THEN press_source.approval_status ELSE 'PENDING_PERMISSION' END, enabled = CASE WHEN excluded.verification_status = 'ENDPOINT_VERIFIED' THEN press_source.enabled ELSE 0 END;
