INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, verification_status, verification_note, endpoint_verified_at, policy_basis, adapter_profile, registry_version) VALUES ('src:daejeon:press', 'org:대전광역시', 'HTML', 'HTMLBoardAdapter', 'https://www.daejeon.go.kr', 'https://www.daejeon.go.kr/drh/board/boardNormalList.do?boardId=normal_0189&menuSeq=1632', '["www.daejeon.go.kr"]', 'ENDPOINT_VERIFIED', '홈페이지 메뉴 ''보도자료''가 연결하는 게시판(normal_0189). robots.txt가 Allow. 원문 주소(ntatcSeq) 열람 확인. 같은 메뉴의 ''대전소식모아보기(자치구)''는 자치구·교육청 자료 모음이라 시청 Source로 쓰지 않았다.', 1791075600, '개별 이용조건(공공누리 유형 등)과 공개 표시 권한은 운영자 확인 전이라 승인 대기 상태다.', '{"link":"boardNormalView\\.do\\?boardId=normal_0189[^\"]*ntatcSeq=(?<id>\\d+)","url":"https://www.daejeon.go.kr/drh/board/boardNormalView.do?boardId=normal_0189&menuSeq=1632&ntatcSeq={id}","title":"text","date":"class=\"date\">\\s*([\\d-]+)"}', 'seed-metro-2026-10-04') ON CONFLICT(source_id) DO UPDATE SET method = excluded.method, adapter = excluded.adapter, homepage_url = excluded.homepage_url, endpoint_url = excluded.endpoint_url, allowed_hosts = excluded.allowed_hosts, verification_status = excluded.verification_status, verification_note = excluded.verification_note, endpoint_verified_at = excluded.endpoint_verified_at, adapter_profile = excluded.adapter_profile, registry_version = excluded.registry_version, approval_status = CASE WHEN excluded.verification_status = 'ENDPOINT_VERIFIED' THEN press_source.approval_status ELSE 'PENDING_PERMISSION' END, enabled = CASE WHEN excluded.verification_status = 'ENDPOINT_VERIFIED' THEN press_source.enabled ELSE 0 END;
